   130→## Decision
   131→
   132→**Hybrid approach based on focus:**
   133→
   134→```typescript
   135→async function insertText(text: string, options: InsertOptions = {}): Promise<void> {
   136→    const { execute = false } = options;
   137→
   138→    // Priority 1: Active terminal
   139→    const terminal = vscode.window.activeTerminal;
   140→    if (isTerminalFocused()) {
   141→        terminal?.sendText(text, execute);
   142→        return;
   143→    }
   144→
   145→    // Priority 2: Active text editor
   146→    const editor = vscode.window.activeTextEditor;
   147→    if (editor && isEditorFocused()) {
   148→        await editor.edit(editBuilder => {
   149→            editBuilder.insert(editor.selection.active, text);
   150→        });
   151→        return;
   152→    }
   153→
   154→    // Priority 3: Fallback to clipboard paste
   155→    await pasteFromClipboard(text);
   156→}
   157→```
