   542→### Complete Message Handler
   543→
   544→```typescript
   545→class DictationHandler {
   546→    private editorManager = new InterimTextManager();
   547→    private terminalInserter = new TerminalInserter();
   548→
   549→    async handleMessage(msg: ServerMessage): Promise<void> {
   550→        // Determine target based on focus
   551→        if (this.isTerminalFocused()) {
   552→            const terminal = vscode.window.activeTerminal;
   553→            if (terminal) {
   554→                this.terminalInserter.handleMessage(terminal, msg);
   555→            }
   556→            return;
   557→        }
   558→
   559→        const editor = vscode.window.activeTextEditor;
   560→        if (!editor) {
   561→            vscode.window.showWarningMessage('No active editor for dictation');
   562→            return;
   563→        }
   564→
   565→        switch (msg.type) {
   566→            case 'interim':
   567→                await this.editorManager.handleInterim(
   568→                    editor,
   569→                    msg.text,
   570→                    msg.is_final
   571→                );
   572→                break;
   573→
   574→            case 'streaming':
   575→                await this.editorManager.handleStreamingToken(
   576→                    editor,
   577→                    msg.token,
   578→                    msg.position
   579→                );
   580→                break;
   581→
   582→            case 'final':
   583→                await this.editorManager.finalize(editor);
   584→                // Execute voice commands after finalization
   585→                for (const cmd of msg.commands) {
   586→                    await this.executeVoiceCommand(cmd);
   587→                }
   588→                break;
   589→
   590→            case 'error':
   591→                await this.editorManager.cancel(editor);
   592→                vscode.window.showErrorMessage(`Dictation error: ${msg.message}`);
   593→                break;
   594→        }
   595→    }
   596→
   597→    private isTerminalFocused(): boolean {
   598→        // VS Code doesn't expose this directly; track via events
   599→        return this.currentFocus === 'terminal';
   600→    }
   601→}
