    except Exception as e:
        # Send error message to client
        try:
            await websocket.send_json({
                "type": "error",
                "data": {
                    "message": str(e)
                }
            })
        except Exception:
            pass  # Connection already closed

    finally:
        # Cleanup
        if websocket in active_connections:
            active_connections.remove(websocket)


