     1→/**
     2→ * VTThought Text Insertion (ADR-007)
     3→ *
     4→ * Manages text insertion into VS Code editor and terminal.
     5→ * Implements interim text display with atomic rewriting.
     6→ */
     7→
     8→import * as vscode from 'vscode';
     9→
    10→/**
    11→ * Server message types from backend WebSocket.
    12→ */
    13→export type ServerMessage =
    14→    | { type: 'interim'; text: string; is_final: boolean; confidence: number; changes: TextChange[] }  // eslint-disable-line @typescript-eslint/naming-convention
    15→    | { type: 'streaming'; token: string; position: number }
    16→    | { type: 'final'; raw: string; cleaned: string; commands: VoiceCommand[] }
    17→    | { type: 'error'; code: string; message: string };
    18→
    19→/**
    20→ * Text edit operation for interim updates.
    21→ */
    22→export interface TextChange {
    23→    start: number;
    24→    deleteCount: number;
    25→    insert: string;
    26→}
    27→
    28→/**
    29→ * Voice command to execute.
    30→ */
    31→export interface VoiceCommand {
    32→    action: string;
    33→    params?: Record<string, unknown>;
    34→    terminal?: boolean;
    35→}
    36→
    37→/**
    38→ * Manages interim text display with rewriting support.
    39→ *
    40→ * Key concepts:
    41→ * - anchor: Fixed position where dictation started (never moves)
    42→ * - interimLength: Current length of interim text (for calculating replacement range)
    43→ * - Atomic replacement: Uses editBuilder.replace() for flicker-free updates
    44→ * - Undo grouping: All interim edits are one undo operation
    45→ *
    46→ * Implements the interim text manager from ADR-007.
    47→ */
    48→export class InterimTextManager {
    49→    // Fixed starting point - never moves during dictation
    50→    private anchor: vscode.Position | null = null;
    51→
    52→    // Current interim text length for calculating replacement range
    53→    private interimLength = 0;
    54→
    55→    // Decoration for gray/italic interim styling
    56→    private readonly interimStyle: vscode.TextEditorDecorationType;
    57→
    58→    constructor() {
    59→        this.interimStyle = vscode.window.createTextEditorDecorationType({
    60→            color: new vscode.ThemeColor('editorGhostText.foreground'),
    61→            fontStyle: 'italic',
    62→            // Optional: add subtle background
    63→            backgroundColor: new vscode.ThemeColor('editor.wordHighlightBackground'),
    64→        });
    65→    }
    66→
    67→    /**
    68→     * Handle an interim result from the server.
    69→     * Replaces all existing interim text with new text.
    70→     */
    71→    async handleInterim(
    72→        editor: vscode.TextEditor,
    73→        text: string,
    74→        isFinal: boolean
    75→    ): Promise<void> {
    76→        // First interim: record anchor position
    77→        if (!this.anchor) {
    78→            this.anchor = editor.selection.active;
    79→        }
    80→
    81→        // Calculate the range of existing interim text
    82→        const interimStart = this.anchor;
    83→        const interimEnd = this.anchor.translate(0, this.interimLength);
    84→        const interimRange = new vscode.Range(interimStart, interimEnd);
    85→
    86→        // Atomic edit: replace entire interim region with new text
    87→        const success = await editor.edit(editBuilder => {
    88→            if (this.interimLength > 0) {
    89→                // Replace existing interim text
    90→                editBuilder.replace(interimRange, text);
    91→            } else {
    92→                // First insertion
    93→                editBuilder.insert(this.anchor!, text);
    94→            }
    95→        }, {
    96→            // Undo grouping: don't create undo stops between interim edits
    97→            undoStopBefore: false,
    98→            undoStopAfter: false,
    99→        });
   100→
   101→        if (!success) {
   102→            console.warn('InterimTextManager: edit failed');
   103→            return;
   104→        }
   105→
   106→        // Update tracked length
   107→        this.interimLength = text.length;
   108→
   109→        // Apply or remove interim styling
   110→        if (!isFinal) {
   111→            const newRange = new vscode.Range(
   112→                this.anchor,
   113→                this.anchor.translate(0, this.interimLength)
   114→            );
   115→            editor.setDecorations(this.interimStyle, [newRange]);
   116→        } else {
   117→            // Final STT result: remove interim styling
   118→            editor.setDecorations(this.interimStyle, []);
   119→        }
   120→
   121→        // Move cursor to end of inserted text
   122→        const newCursorPos = this.anchor.translate(0, this.interimLength);
   123→        editor.selection = new vscode.Selection(newCursorPos, newCursorPos);
   124→    }
   125→
   126→    /**
   127→     * Handle streaming LLM cleanup tokens.
   128→     * First token replaces interim text; subsequent tokens append.
   129→     */
   130→    async handleStreamingToken(
   131→        editor: vscode.TextEditor,
   132→        token: string,
   133→        position: number  // Character position in the cleaned output
   134→    ): Promise<void> {
   135→        if (!this.anchor) {
   136→            return;
   137→        }
   138→
   139→        // Clear interim styling on first token
   140→        if (position === 0) {
   141→            editor.setDecorations(this.interimStyle, []);
   142→        }
   143→
   144→        if (position === 0 && this.interimLength > 0) {
   145→            // First token: replace entire interim text
   146→            const interimRange = new vscode.Range(
   147→                this.anchor,
   148→                this.anchor.translate(0, this.interimLength)
   149→            );
   150→            await editor.edit(eb => eb.replace(interimRange, token), {
   151→                undoStopBefore: false,
   152→                undoStopAfter: false,
   153→            });
   154→            this.interimLength = token.length;
   155→        } else {
   156→            // Subsequent tokens: append
   157→            const insertPos = this.anchor.translate(0, this.interimLength);
   158→            await editor.edit(eb => eb.insert(insertPos, token), {
   159→                undoStopBefore: false,
   160→                undoStopAfter: false,
   161→            });
   162→            this.interimLength += token.length;
   163→        }
   164→
   165→        // Move cursor to end
   166→        const newCursorPos = this.anchor.translate(0, this.interimLength);
   167→        editor.selection = new vscode.Selection(newCursorPos, newCursorPos);
   168→    }
   169→
   170→    /**
   171→     * Finalize the dictation session.
   172→     * Creates undo stop so entire dictation is one undo operation.
   173→     */
   174→    async finalize(editor: vscode.TextEditor): Promise<void> {
   175→        if (!this.anchor) {
   176→            return;
   177→        }
   178→
   179→        // Create final undo stop - entire dictation is now one undo
   180→        await editor.edit(() => {}, {
   181→            undoStopBefore: false,
   182→            undoStopAfter: true,  // End the undo group
   183→        });
   184→
   185→        // Clear styling
   186→        editor.setDecorations(this.interimStyle, []);
   187→
   188→        // Reset state
   189→        this.reset();
   190→    }
   191→
   192→    /**
   193→     * Cancel dictation and remove any interim text.
   194→     */
   195→    async cancel(editor: vscode.TextEditor): Promise<void> {
   196→        if (!this.anchor || this.interimLength === 0) {
   197→            this.reset();
   198→            return;
   199→        }
   200→
   201→        // Delete the interim text
   202→        const interimRange = new vscode.Range(
   203→            this.anchor,
   204→            this.anchor.translate(0, this.interimLength)
   205→        );
   206→        await editor.edit(eb => eb.delete(interimRange));
   207→
   208→        // Clear styling and reset
   209→        editor.setDecorations(this.interimStyle, []);
   210→        this.reset();
   211→    }
   212→
   213→    reset(): void {
   214→        this.anchor = null;
   215→        this.interimLength = 0;
   216→    }
   217→
   218→    isActive(): boolean {
   219→        return this.anchor !== null;
   220→    }
