     1→# ADR-015: Error Handling & Recovery
     2→
     3→**Status:** Proposed
     4→**Date:** 2026-01-30
     5→**Decision Makers:** TBD
     6→
     7→---
     8→
     9→## Context
    10→
    11→Network failures, backend issues, and device problems will occur. Graceful error handling is critical for user trust. Users need to know what went wrong, whether their audio was lost, and what to do next.
    12→
    13→## Decision Drivers
    14→
    15→- **Transparency**: Users understand what happened
    16→- **Recovery**: Automatic recovery when possible
    17→- **No data loss**: Minimize lost recordings
    18→- **Non-blocking**: Errors shouldn't freeze the UI
    19→
    20→## Error Categories
    21→
    22→```
    23→┌─────────────────────────────────────────────────────────────────────────────┐
    24→│                    ERROR CATEGORIES                                          │
    25→├─────────────────────────────────────────────────────────────────────────────┤
    26→│                                                                              │
    27→│  CONNECTION ERRORS                                                           │
    28→│  ├─ WebSocket fails to connect                                              │
    29→│  ├─ WebSocket disconnects mid-recording                                     │
    30→│  ├─ Backend unreachable (DNS, network)                                      │
    31→│  └─ TLS/certificate errors                                                  │
    32→│                                                                              │
    33→│  BACKEND ERRORS                                                              │
    34→│  ├─ Timeout (Whisper slow, LLM slow)                                        │
    35→│  ├─ Server error (500, OOM, GPU busy)                                       │
    36→│  ├─ Rate limited (429)                                                      │
    37→│  └─ Malformed response                                                      │
    38→│                                                                              │
    39→│  AUTHENTICATION ERRORS                                                       │
    40→│  ├─ Token expired                                                           │
    41→│  ├─ Token revoked/invalid                                                   │
    42→│  └─ OAuth flow failed                                                       │
    43→│                                                                              │
    44→│  DEVICE ERRORS                                                               │
    45→│  ├─ Microphone not found                                                    │
    46→│  ├─ Microphone permission denied                                            │
    47→│  ├─ Audio device disconnected                                               │
    48→│  └─ Audio capture failed                                                    │
    49→│                                                                              │
    50→│  CLIENT ERRORS                                                               │
    51→│  ├─ WebView crashed                                                         │
    52→│  ├─ Extension host restarted                                                │
    53→│  └─ Memory pressure                                                         │
    54→│                                                                              │
    55→└─────────────────────────────────────────────────────────────────────────────┘
    56→```
    57→
    58→## Decision
    59→
    60→Implement **layered error handling** with automatic recovery, clear user feedback, and graceful degradation.
    61→
    62→## Error Handling Strategy
    63→
    64→### 1. Connection Errors
    65→
    66→```typescript
    67→interface ConnectionState {
    68→    status: 'connected' | 'connecting' | 'disconnected' | 'reconnecting';
    69→    lastError: Error | null;
    70→    reconnectAttempts: number;
    71→}
    72→
    73→class WebSocketManager {
    74→    private ws: WebSocket | null = null;
    75→    private state: ConnectionState = {
    76→        status: 'disconnected',
    77→        lastError: null,
    78→        reconnectAttempts: 0
    79→    };
    80→
    81→    // Reconnection config
    82→    private readonly maxReconnectAttempts = 5;
    83→    private readonly baseDelay = 1000;  // 1 second
    84→    private readonly maxDelay = 30000;  // 30 seconds
    85→
    86→    async connect(url: string, token: string): Promise<void> {
    87→        this.state.status = 'connecting';
    88→
    89→        try {
    90→            this.ws = new WebSocket(`${url}?token=${token}`);
    91→
    92→            this.ws.onopen = () => {
    93→                this.state.status = 'connected';
    94→                this.state.reconnectAttempts = 0;
    95→                this.state.lastError = null;
    96→            };
    97→
    98→            this.ws.onclose = (event) => {
    99→                if (event.code !== 1000) {  // Abnormal close
   100→                    this.handleDisconnect(new Error(`WebSocket closed: ${event.reason}`));
   101→                }
   102→            };
   103→
   104→            this.ws.onerror = (error) => {
   105→                this.handleDisconnect(error);
   106→            };
   107→
   108→        } catch (error) {
   109→            this.handleDisconnect(error);
   110→        }
   111→    }
   112→
   113→    private async handleDisconnect(error: Error): Promise<void> {
   114→        this.state.status = 'disconnected';
   115→        this.state.lastError = error;
   116→
   117→        // Notify UI
   118→        this.emit('disconnected', error);
   119→
   120→        // Attempt reconnection with exponential backoff
   121→        if (this.state.reconnectAttempts < this.maxReconnectAttempts) {
   122→            await this.attemptReconnect();
   123→        } else {
   124→            this.emit('reconnectFailed', error);
   125→        }
   126→    }
   127→
   128→    private async attemptReconnect(): Promise<void> {
   129→        this.state.status = 'reconnecting';
   130→        this.state.reconnectAttempts++;
   131→
   132→        // Exponential backoff with jitter
   133→        const delay = Math.min(
   134→            this.baseDelay * Math.pow(2, this.state.reconnectAttempts - 1),
   135→            this.maxDelay
   136→        );
   137→        const jitter = delay * 0.2 * Math.random();
   138→
   139→        await sleep(delay + jitter);
   140→
   141→        try {
   142→            await this.connect(this.url, this.token);
   143→        } catch (error) {
   144→            // Will trigger handleDisconnect again
   145→        }
   146→    }
   147→}
   148→```
   149→
   150→### 2. Recording Recovery
   151→
   152→```typescript
   153→class RecordingSession {
   154→    private audioBuffer: ArrayBuffer[] = [];
   155→    private isSent = false;
   156→
   157→    /**
   158→     * Buffer audio locally in case of connection issues.
   159→     */
   160→    addChunk(chunk: ArrayBuffer): void {
   161→        this.audioBuffer.push(chunk);
   162→
   163→        // Also try to send immediately
   164→        if (this.ws.isConnected()) {
   165→            this.ws.send(chunk);
   166→        }
   167→    }
   168→
   169→    /**
   170→     * If connection was lost, we have the audio buffered.
   171→     * Can retry sending when reconnected.
   172→     */
   173→    async retryWithBuffer(): Promise<void> {
   174→        if (this.isSent || this.audioBuffer.length === 0) {
   175→            return;
   176→        }
   177→
   178→        // Combine all chunks
   179→        const fullAudio = this.combineChunks(this.audioBuffer);
   180→
   181→        // Send as single payload after reconnection
   182→        await this.ws.send(fullAudio);
   183→        this.isSent = true;
   184→    }
   185→
   186→    /**
   187→     * Clear buffer after successful processing.
   188→     */
   189→    clear(): void {
   190→        this.audioBuffer = [];
   191→        this.isSent = false;
   192→    }
   193→}
   194→```
   195→
   196→### 3. Backend Errors
   197→
   198→```typescript
   199→interface BackendError {
   200→    code: string;
   201→    message: string;
   202→    retryable: boolean;
   203→    retryAfter?: number;  // seconds
   204→}
   205→
   206→class BackendErrorHandler {
   207→    handleError(error: BackendError, ui: StatusBarUI): void {
   208→        switch (error.code) {
   209→            case 'TIMEOUT':
   210→                this.handleTimeout(error, ui);
   211→                break;
   212→
   213→            case 'RATE_LIMITED':
   214→                this.handleRateLimit(error, ui);
   215→                break;
   216→
   217→            case 'SERVER_ERROR':
   218→                this.handleServerError(error, ui);
   219→                break;
   220→
   221→            case 'TRANSCRIPTION_FAILED':
   222→                this.handleTranscriptionError(error, ui);
   223→                break;
   224→
   225→            default:
   226→                this.handleUnknownError(error, ui);
   227→        }
   228→    }
   229→
   230→    private handleTimeout(error: BackendError, ui: StatusBarUI): void {
   231→        ui.setError('Processing took too long');
   232→
   233→        vscode.window.showWarningMessage(
   234→            'Transcription timed out. The server may be busy.',
   235→            'Retry',
   236→            'Cancel'
   237→        ).then(action => {
   238→            if (action === 'Retry') {
   239→                vscode.commands.executeCommand('voicecode.retryLast');
