   249→        vscode.window.showWarningMessage(
   250→            `Too many requests. Please wait ${waitTime} seconds.`
   251→        );
   252→
   253→        // Auto-recover after wait time
   254→        setTimeout(() => {
   255→            ui.setIdle();
   256→        }, waitTime * 1000);
   257→    }
   258→
   259→    private handleServerError(error: BackendError, ui: StatusBarUI): void {
   260→        ui.setError('Server error');
   261→
   262→        vscode.window.showErrorMessage(
   263→            'The server encountered an error. Please try again.',
   264→            'Retry',
   265→            'View Logs'
   266→        ).then(action => {
   267→            if (action === 'Retry') {
   268→                vscode.commands.executeCommand('voicecode.retryLast');
