   421→## Circuit Breaker Pattern
   422→
   423→Prevent cascading failures when backend is unhealthy:
   424→
   425→```typescript
   426→enum CircuitState {
   427→    CLOSED,      // Normal operation
   428→    OPEN,        // Failing, reject requests
   429→    HALF_OPEN    // Testing if recovered
   430→}
   431→
   432→class CircuitBreaker {
   433→    private state = CircuitState.CLOSED;
   434→    private failures = 0;
   435→    private lastFailure: number = 0;
   436→    private successesInHalfOpen = 0;
   437→
   438→    // Configuration
   439→    private readonly failureThreshold = 5;
   440→    private readonly resetTimeout = 30000;  // 30 seconds
   441→    private readonly successThreshold = 2;
   442→
   443→    async execute<T>(operation: () => Promise<T>): Promise<T> {
   444→        if (this.state === CircuitState.OPEN) {
   445→            if (Date.now() - this.lastFailure > this.resetTimeout) {
   446→                this.state = CircuitState.HALF_OPEN;
   447→            } else {
   448→                throw new CircuitOpenError('Service temporarily unavailable');
   449→            }
   450→        }
   451→
   452→        try {
   453→            const result = await operation();
   454→            this.onSuccess();
   455→            return result;
   456→        } catch (error) {
   457→            this.onFailure();
   458→            throw error;
   459→        }
   460→    }
   461→
   462→    private onSuccess(): void {
   463→        if (this.state === CircuitState.HALF_OPEN) {
   464→            this.successesInHalfOpen++;
   465→            if (this.successesInHalfOpen >= this.successThreshold) {
   466→                this.state = CircuitState.CLOSED;
   467→                this.failures = 0;
   468→                this.successesInHalfOpen = 0;
   469→            }
   470→        } else {
   471→            this.failures = 0;
   472→        }
   473→    }
   474→
   475→    private onFailure(): void {
   476→        this.failures++;
   477→        this.lastFailure = Date.now();
   478→
   479→        if (this.state === CircuitState.HALF_OPEN) {
   480→            this.state = CircuitState.OPEN;
   481→            this.successesInHalfOpen = 0;
   482→        } else if (this.failures >= this.failureThreshold) {
   483→            this.state = CircuitState.OPEN;
   484→        }
   485→    }
   486→
   487→    getState(): CircuitState {
   488→        return this.state;
   489→    }
   490→}
   491→```
