   602→```typescript
   603→class DictationController {
   604→    private wsManager: WebSocketManager;
   605→    private circuitBreaker: CircuitBreaker;
   606→    private errorLogger: ErrorLogger;
   607→    private ui: StatusBarUI;
   608→
   609→    async startRecording(): Promise<void> {
   610→        // Check circuit breaker first
   611→        if (this.circuitBreaker.getState() === CircuitState.OPEN) {
   612→            this.ui.setError('Service unavailable');
   613→            vscode.window.showWarningMessage(
   614→                'Voice Code is temporarily unavailable. Please try again later.'
   615→            );
   616→            return;
   617→        }
   618→
   619→        try {
   620→            // Ensure connected
   621→            if (!this.wsManager.isConnected()) {
   622→                await this.wsManager.connect(this.backendUrl, this.token);
   623→            }
   624→
   625→            this.ui.setRecording();
   626→            await this.audioCapture.start();
   627→
   628→        } catch (error) {
   629→            this.errorLogger.logError('recording_start', error);
   630→
   631→            if (error instanceof DeviceError) {
   632→                this.deviceErrorHandler.handleDeviceError(error, this.ui);
   633→            } else if (error instanceof ConnectionError) {
   634→                this.ui.setError('Cannot connect');
   635→                this.wsManager.attemptReconnect();
   636→            }
   637→        }
   638→    }
   639→
   640→    async stopRecording(): Promise<void> {
   641→        this.ui.setProcessing();
   642→
   643→        try {
   644→            await this.circuitBreaker.execute(async () => {
   645→                const result = await this.sendAudioAndWaitForResult();
   646→                return result;
   647→            });
   648→
   649→            this.ui.setIdle();
   650→
   651→        } catch (error) {
   652→            this.errorLogger.logError('processing', error);
   653→
   654→            if (error instanceof CircuitOpenError) {
   655→                this.ui.setError('Service unavailable');
   656→            } else if (error instanceof BackendError) {
   657→                this.backendErrorHandler.handleError(error, this.ui);
   658→            } else if (error instanceof AuthError) {
   659→                await this.authErrorHandler.handleAuthError(error, this.ui);
   660→            } else {
   661→                this.ui.setError('Processing failed');
   662→            }
   663→        }
   664→    }
   665→}
   666→```
   667→
   668→## Consequences
   669→
   670→### Positive
   671→- **Resilient**: Automatic recovery from transient failures
   672→- **Transparent**: Users understand what went wrong
   673→- **Actionable**: Clear next steps for users
   674→- **Protected**: Circuit breaker prevents cascade failures
   675→
   676→### Negative
   677→- **Complexity**: Multiple error handlers to maintain
   678→- **Testing**: Many error paths to test
   679→- **Buffering**: Memory overhead for audio buffering
   680→
   681→### Tradeoffs
   682→- Buffer audio locally (uses memory, but enables retry)
   683→- Auto-reconnect (may seem slow, but recovers gracefully)
   684→- Circuit breaker (may block valid requests, but protects system)
   685→
   686→## Related ADRs
   687→- ADR-004: Audio Streaming Protocol (WebSocket handling)
   688→- ADR-010: Security Model (auth errors)
   689→- ADR-013: Extension UI (error display)
