class DeviceErrorHandler {
    handleDeviceError(error: DeviceError, ui: StatusBarUI): void {
        switch (error.code) {
            case 'NO_MICROPHONE':
                ui.setError('No microphone');
                vscode.window.showErrorMessage(
                    'No microphone found. Please connect a microphone and try again.',
                    'Check Settings'
                ).then(action => {
