                ui.setError('Audio capture failed');
                vscode.window.showErrorMessage(
                    'Failed to capture audio. Please check your microphone.',
                    'Test Microphone'
                ).then(action => {
                    if (action === 'Test Microphone') {
                        vscode.commands.executeCommand('voicecode.testMicrophone');
                    }
                });
                break;
        }
    }
}
