    37→
    38→/**
    39→ * Voice command registry.
    40→ * Based on ADR-008 command categories.
    41→ */
    42→const VOICE_COMMANDS: VoiceCommand[] = [
    43→    // Execution Commands (Terminal/Claude Code)
    44→    {
    45→        trigger: ['enter', 'send', 'submit', 'run that', 'execute'],
    46→        action: 'terminal.send-enter',
    47→        terminal: true
    48→    },
