    51→        action: 'terminal.send-ctrl-c',
    52→        terminal: true
    53→    },
    54→
    55→    // Editing Commands
    56→    {
    57→        trigger: ['delete that', 'undo', 'scratch that'],
    58→        action: 'undo'
    59→    },
    60→    {
    61→        trigger: ['clear line', 'delete line'],
    62→        action: 'editor.action.deleteLines'
    63→    },
    64→    {
    65→        trigger: ['select all'],
    66→        action: 'editor.action.selectAll'
    67→    },
    68→    {
    69→        trigger: ['new line', 'newline'],
    70→        action: 'type',
    71→        params: () => ({ text: '\n' })
    72→    },
    73→    {
    74→        trigger: ['tab'],
    75→        action: 'type',
    76→        params: () => ({ text: '\t' })
    77→    },
    78→
    79→    // Navigation Commands
    80→    {
    81→        trigger: ['go to line'],
    82→        action: 'workbench.action.gotoLine',
    83→        params: (match) => {
    84→            const num = match.match(/go to line (\d+)/i)?.[1];
    85→            return num ? { lineNumber: parseInt(num) } : null;
    86→        }
    87→    },
    88→
    89→    // VS Code Commands
    90→    {
    91→        trigger: ['save file', 'save'],
    92→        action: 'workbench.action.files.save'
    93→    },
    94→    {
    95→        trigger: ['close file', 'close tab'],
    96→        action: 'workbench.action.closeActiveEditor'
    97→    },
    98→    {
    99→        trigger: ['open terminal', 'show terminal'],
   100→        action: 'workbench.action.terminal.toggleTerminal'
   101→    },
   102→    {
   103→        trigger: ['command palette'],
   104→        action: 'workbench.action.showCommands'
   105→    },
   106→
   107→    // Dictation Control
   108→    {
   109→        trigger: ['stop listening', 'pause'],
   110→        action: 'voicecode.stopListening'
   111→    }
   112→];
   113→
   114→/**
   115→ * Parses voice commands from transcription.
   116→ * Implements keyword-based command detection from ADR-008.
   117→ */
   118→export class CommandParser {
   119→    private commands: VoiceCommand[];
   120→
   121→    constructor(commands: VoiceCommand[] = VOICE_COMMANDS) {
   122→        this.commands = commands;
   123→    }
   124→
   125→    parse(transcription: string): ParsedTranscription {
   126→        let text = transcription;
   127→        const foundCommands: Command[] = [];
   128→
   129→        // Check for commands at the end of transcription
   130→        for (const cmd of this.commands) {
   131→            for (const trigger of cmd.trigger) {
   132→                const regex = new RegExp(`\\s*${this.escapeRegex(trigger)}\\s*$`, 'i');
   133→                if (regex.test(text)) {
   134→                    text = text.replace(regex, '').trim();
   135→                    foundCommands.push({
   136→                        action: cmd.action,
   137→                        params: cmd.params?.(transcription) ?? undefined,
   138→                        terminal: cmd.terminal
   139→                    });
   140→                }
   141→            }
   142→        }
   143→
   144→        return {
   145→            text,
   146→            commands: foundCommands.reverse(),  // Execute in order spoken
   147→            hasTrailingCommand: foundCommands.length > 0
   148→        };
   149→    }
   150→
   151→    private escapeRegex(str: string): string {
   152→        return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
   153→    }
   154→}
   155→
   156→/**
   157→ * Executes parsed voice commands.
   158→ */
   159→export class CommandExecutor {
   160→    async execute(command: Command): Promise<void> {
   161→        if (command.terminal) {
   162→            await this.executeTerminalCommand(command);
   163→        } else {
   164→            await vscode.commands.executeCommand(
   165→                command.action,
   166→                command.params
   167→            );
   168→        }
   169→    }
   170→
   171→    private async executeTerminalCommand(command: Command): Promise<void> {
   172→        const terminal = vscode.window.activeTerminal;
   173→        if (!terminal) {
   174→            vscode.window.showWarningMessage('No active terminal for command');
   175→            return;
   176→        }
   177→
   178→        switch (command.action) {
   179→            case 'terminal.send-enter':
   180→                terminal.sendText('', true);  // Empty string with execute=true
   181→                break;
   182→            case 'terminal.send-ctrl-c':
   183→                terminal.sendText('\x03', false);
   184→                break;
   185→            case 'terminal.clear-line':
   186→                terminal.sendText('\u0015', false);  // Ctrl+U
   187→                break;
   188→            default:
   189→                vscode.window.showWarningMessage(`Unknown terminal command: ${command.action}`);
   190→        }
   191→    }
   192→}
   193→
   194→/**
   195→ * Disambiguation for homophones (similar-sounding words).
   196→ * From ADR-008.
   197→ */
   198→const HOMOPHONES: Record<string, string[]> = {
   199→    'enter': ['inter', 'inner'],
   200→    'send': ['sent', 'scent'],
   201→    'delete': ['the lead', 'dilute'],
   202→    'undo': ['un do', 'and do']
   203→};
   204→
   205→/**
   206→ * Normalize text by applying homophone corrections.
   207→ */
   208→export function normalizeCommand(text: string): string {
   209→    let normalized = text.toLowerCase();
   210→    for (const [correct, variants] of Object.entries(HOMOPHONES)) {
   211→        for (const variant of variants) {
   212→            normalized = normalized.replace(variant, correct);
   213→        }
   214→    }
   215→    return normalized;
   216→}
   217→
   218→/**
   219→ * Process transcription and execute commands.
   220→ * Full pipeline from ADR-008.
   221→ */
   222→export async function processTranscription(rawText: string): Promise<void> {
   223→    const parser = new CommandParser();
   224→    const executor = new CommandExecutor();
   225→
   226→    // Parse commands
   227→    const parsed = parser.parse(rawText);
   228→
   229→    // Insert text (if any)
   230→    if (parsed.text) {
   231→        await insertText(parsed.text);
   232→    }
   233→
   234→    // Execute commands
   235→    for (const cmd of parsed.commands) {
   236→        await executor.execute(cmd);
   237→    }
   238→}
   239→
   240→/**
   241→ * Insert text at cursor position.
   242→ */
   243→async function insertText(text: string): Promise<void> {
   244→    const editor = vscode.window.activeTextEditor;
   245→    if (!editor) {
   246→        return;
   247→    }
   248→
   249→    await editor.edit(editBuilder => {
   250→        editBuilder.insert(editor.selection.active, text);
   251→    });
   252→}
   253→
   254→// Export default parser instance
   255→export const commandParser = new CommandParser();
   256→export const commandExecutor = new CommandExecutor();
   257→

