import * as vscode from 'vscode';

/**
 * Message types between extension and WebView
 */
interface AudioDataMessage {
    type: 'audio';
    data: number[]; // Float32Array serialized as array
    sampleRate: number;
}

interface ReadyMessage {
    type: 'ready';
}

interface ErrorMessage {
    type: 'error';
    message: string;
}

type WebViewMessage = AudioDataMessage | ReadyMessage | ErrorMessage;

/**
 * Audio capture WebView provider
 * Implements audio capture using Web Audio API in a WebView
 * Per ADR-003: Uses Web Audio API for cross-platform audio capture
 */
export class VoiceInputViewProvider implements vscode.WebviewViewProvider {
    public static readonly viewType = 'vtthought.voiceInputView';

    private _view?: vscode.WebviewView;

    // Callbacks for audio data events
    private onAudioDataCallbacks: ((data: Float32Array, sampleRate: number) => void)[] = [];
    private onErrorCallbacks: ((error: string) => void)[] = [];

    constructor(private readonly _extensionUri: vscode.Uri) {}

    /**
     * Register callback for audio data
     */
    public onAudioData(callback: (data: Float32Array, sampleRate: number) => void): void {
        this.onAudioDataCallbacks.push(callback);
    }

    /**
     * Register callback for errors
     */
    public onError(callback: (error: string) => void): void {
        this.onErrorCallbacks.push(callback);
    }

    /**
     * Resolve the WebView view
     */
    public resolveWebviewView(
        webviewView: vscode.WebviewView,
        context: vscode.WebviewViewResolveContext,
        _token: vscode.CancellationToken
    ): void {
        this._view = webviewView;

        webviewView.webview.options = {
            enableScripts: true,
            localResourceRoots: [this._extensionUri]
        };

        webviewView.webview.html = this._getHtmlForWebview(webviewView.webview);

        // Handle messages from WebView
        webviewView.webview.onDidReceiveMessage(
            (message: WebViewMessage) => {
                switch (message.type) {
                    case 'audio':
                        // Convert array back to Float32Array
                        const audioData = new Float32Array(message.data);
                        this.onAudioDataCallbacks.forEach(cb => cb(audioData, message.sampleRate));
                        break;
                    case 'ready':
                        // WebView is ready to accept commands
                        break;
                    case 'error':
                        this.onErrorCallbacks.forEach(cb => cb(message.message));
                        break;
                }
            },
            undefined,
            undefined
        );
    }

    /**
     * Send start recording command to WebView
     */
    public startRecording(): void {
        if (this._view) {
            this._view.webview.postMessage({ command: 'start' });
        }
    }

    /**
     * Send stop recording command to WebView
     */
    public stopRecording(): void {
        if (this._view) {
            this._view.webview.postMessage({ command: 'stop' });
        }
    }

    /**
     * Get the WebView HTML
     */
    private _getHtmlForWebview(webview: vscode.Webview): string {
        return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline' 'unsafe-eval'; style-src 'unsafe-inline';">
    <title>VTThought Voice Input</title>
    <style>
        body {
            padding: 10px;
            font-family: var(--vscode-font-family);
            font-size: var(--vscode-font-size);
            color: var(--vscode-foreground);
            background-color: var(--vscode-editor-background);
        }
        .container {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }
        .status {
            padding: 8px;
            border-radius: 4px;
            font-size: 12px;
        }
        .status.idle {
            background-color: var(--vscode-editorInfo-background);
            color: var(--vscode-editorInfo-foreground);
        }
        .status.recording {
            background-color: var(--vscode-errorBackground);
            color: var(--vscode-errorForeground);
            animation: pulse 1.5s infinite;
        }
        .status.error {
            background-color: var(--vscode-editorWarningBackground);
            color: var(--vscode-editorWarning-foreground);
        }
        @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.7; }
        }
        .level-meter {
            height: 8px;
            background-color: var(--vscode-progressBar-background);
            border-radius: 4px;
            overflow: hidden;
        }
        .level-meter-fill {
            height: 100%;
            background-color: var(--vscode-progressBar-foreground);
            width: 0%;
            transition: width 0.05s ease-out;
        }
        .info {
            font-size: 11px;
            color: var(--vscode-descriptionForeground);
        }
    </style>
</head>
<body>
    <div class="container">
        <div id="status" class="status idle">
            Ready - Press Ctrl+Alt+V to record
        </div>
        <div class="level-meter">
            <div id="levelMeter" class="level-meter-fill"></div>
        </div>
        <div class="info">
            Sample Rate: <span id="sampleRate">-</span> Hz<br>
            Chunk Size: <span id="chunkSize">-</span> samples
        </div>
    </div>

    <script>
        (function() {
            const vscode = acquireVsCodeApi();

            // Audio context and nodes
            let audioContext: AudioContext | null = null;
            let mediaStream: MediaStream | null = null;
            let source: MediaStreamAudioSourceNode | null = null;
            let processorNode: AudioWorkletNode | null = null;
            let scriptProcessor: ScriptProcessorNode | null = null;

            // Configuration
            const TARGET_SAMPLE_RATE = 16000; // Whisper optimal
            const BUFFER_SIZE = 4096; // ~256ms at 16kHz

            // DOM elements
            const statusEl = document.getElementById('status');
            const levelMeterEl = document.getElementById('levelMeter');
            const sampleRateEl = document.getElementById('sampleRate');
            const chunkSizeEl = document.getElementById('chunkSize');

            // Update status display
            function setStatus(state: string, message: string) {
                statusEl.className = 'status ' + state;
                statusEl.textContent = message;
            }

            // Update level meter
            function updateLevelMeter(rms: number) {
                // Convert RMS to percentage (0-100)
                // Typical speech RMS is around 0.01-0.1
                const level = Math.min(100, Math.max(0, rms * 1000));
                levelMeterEl.style.width = level + '%';
            }

            // Calculate RMS of audio samples
            function calculateRMS(samples: Float32Array): number {
                let sum = 0;
                for (let i = 0; i < samples.length; i++) {
                    sum += samples[i] * samples[i];
                }
                return Math.sqrt(sum / samples.length);
            }

            // Send audio data to extension
            function sendAudioData(samples: Float32Array) {
                // Update level meter
                const rms = calculateRMS(samples);
                updateLevelMeter(rms);

                // Send to extension
                vscode.postMessage({
                    type: 'audio',
                    data: Array.from(samples),
                    sampleRate: TARGET_SAMPLE_RATE
                });
            }

            // AudioWorklet processor code (inline version)
            const workletCode = \`
                class AudioProcessor extends AudioWorkletProcessor {
                    constructor() {
                        super();
                        this.buffer = [];
                        this.bufferSize = \${BUFFER_SIZE};
                    }

                    process(inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean {
                        const input = inputs[0];
                        if (input.length > 0) {
                            const samples = input[0];
                            // Convert stereo to mono if needed
                            for (let i = 0; i < samples.length; i++) {
                                this.buffer.push(samples[i]);
                            }

                            if (this.buffer.length >= this.bufferSize) {
                                const chunk = new Float32Array(this.buffer.splice(0, this.bufferSize));
                                this.port.postMessage(chunk);
                            }
                        }
                        return true;
                    }
                }

                registerProcessor('audio-processor', AudioProcessor);
            \`;

            // Start audio capture
            async function startCapture() {
                try {
                    setStatus('idle', 'Requesting microphone access...');

                    // Get user media with optimal constraints
                    mediaStream = await navigator.mediaDevices.getUserMedia({
                        audio: {
                            sampleRate: TARGET_SAMPLE_RATE,
                            channelCount: 1,
                            echoCancellation: true,
                            noiseSuppression: true,
                            autoGainControl: true
                        }
                    });

                    // Create audio context
                    audioContext = new AudioContext({ sampleRate: TARGET_SAMPLE_RATE });

                    // Update info display
                    sampleRateEl.textContent = audioContext.sampleRate.toString();
                    chunkSizeEl.textContent = BUFFER_SIZE.toString();

                    // Create source
                    source = audioContext.createMediaStreamSource(mediaStream);

                    // Try to use AudioWorklet (preferred)
                    try {
                        const blob = new Blob([workletCode], { type: 'application/javascript' });
                        const workletUrl = URL.createObjectURL(blob);
                        await audioContext.audioWorklet.addModule(workletUrl);
                        URL.revokeObjectURL(workletUrl);

                        processorNode = new AudioWorkletNode(audioContext, 'audio-processor');
                        processorNode.port.onmessage = (e: MessageEvent) => {
                            sendAudioData(e.data as Float32Array);
                        };

                        source.connect(processorNode);
                        setStatus('recording', 'Recording... (Release key to stop)');
                    } catch (workletError) {
                        // Fallback to ScriptProcessorNode
                        console.warn('AudioWorklet failed, using ScriptProcessorNode fallback:', workletError);

                        let buffer: number[] = [];

                        scriptProcessor = audioContext.createScriptProcessor(
                            BUFFER_SIZE,
                            1,
                            1
                        );

                        scriptProcessor.onaudioprocess = (e: AudioProcessingEvent) => {
                            const samples = e.inputBuffer.getChannelData(0);
                            sendAudioData(new Float32Array(samples));
                        };

                        source.connect(scriptProcessor);
                        scriptProcessor.connect(audioContext.destination);
                        setStatus('recording', 'Recording... (Release key to stop)');
                    }

                    vscode.postMessage({ type: 'ready' });

                } catch (error) {
                    console.error('Failed to start audio capture:', error);
                    let errorMsg = 'Failed to start recording';
                    if (error instanceof Error) {
                        if (error.name === 'NotAllowedError') {
                            errorMsg = 'Microphone permission denied. Please allow microphone access in your browser settings.';
                        } else if (error.name === 'NotFoundError') {
                            errorMsg = 'No microphone found. Please connect a microphone.';
                        } else {
                            errorMsg = error.message;
                        }
                    }
                    setStatus('error', errorMsg);
                    vscode.postMessage({ type: 'error', message: errorMsg });
                }
            }

            // Stop audio capture
            function stopCapture() {
                setStatus('idle', 'Stopping...');

                // Disconnect and cleanup
                if (processorNode) {
                    processorNode.disconnect();
                    processorNode = null;
                }

                if (scriptProcessor) {
                    scriptProcessor.disconnect();
                    scriptProcessor = null;
                }

                if (source) {
                    source.disconnect();
                    source = null;
                }

                if (mediaStream) {
                    mediaStream.getTracks().forEach(track => track.stop());
                    mediaStream = null;
                }

                if (audioContext) {
                    audioContext.close();
                    audioContext = null;
                }

                levelMeterEl.style.width = '0%';
                setStatus('idle', 'Ready - Press Ctrl+Alt+V to record');
            }

            // Listen for messages from extension
            window.addEventListener('message', (event: MessageEvent) => {
                const command = event.data.command;
                if (command === 'start') {
                    startCapture();
                } else if (command === 'stop') {
                    stopCapture();
                }
            });

            // Auto-start on load if extension signals it
            vscode.postMessage({ type: 'ready' });
        })();
    </script>
</body>
</html>`;
    }
}

# ADR-008: Voice Commands

**Status:** Proposed
**Date:** 2026-01-30
**Decision Makers:** TBD

---

## Context

Users need to control VS Code and trigger actions (Enter, send, delete) via voice. This requires parsing voice commands from transcription and executing appropriate VS Code actions.

## Decision Drivers

- **Natural language**: Commands should feel natural to speak
- **Reliability**: Commands must be recognized accurately
- **Extensibility**: Easy to add new commands
- **Non-interference**: Commands shouldn't trigger accidentally

## Command Categories

```
┌──────────────────────────────────────────────────────────────────────┐
│                    VOICE COMMAND CATEGORIES                           │
├──────────────────────────────────────────────────────────────────────┤
│                                                                       │
│  1. EXECUTION COMMANDS (Terminal/Claude Code)                         │
│     ├─ "enter" / "send" / "submit"    → Execute command              │
│     ├─ "run that"                     → Execute and wait             │
│     └─ "cancel"                       → Ctrl+C                       │
│                                                                       │
│  2. EDITING COMMANDS                                                  │
│     ├─ "delete that" / "undo"         → Delete last input            │
│     ├─ "clear line"                   → Clear current line           │
│     ├─ "select all"                   → Select all text              │
│     └─ "new line"                     → Insert line break            │
│                                                                       │
│  3. NAVIGATION COMMANDS                                               │
│     ├─ "go to line [N]"               → Navigate to line             │
│     ├─ "go to file [name]"            → Open file                    │
│     └─ "scroll up/down"               → Scroll view                  │
│                                                                       │
│  4. VS CODE COMMANDS                                                  │
│     ├─ "save file"                    → Ctrl+S                       │
│     ├─ "close file"                   → Close active editor          │
│     ├─ "open terminal"                → Toggle terminal              │
│     └─ "command palette"              → Ctrl+Shift+P                 │
│                                                                       │
│  5. DICTATION CONTROL                                                 │
│     ├─ "stop listening"               → Pause voice input            │
│     ├─ "scratch that"                 → Delete last dictation        │
│     └─ "correction: [word]"           → Replace last word            │
│                                                                       │
└──────────────────────────────────────────────────────────────────────┘
```

## Options Considered

### Option A: Keyword Detection (Recommended)

Parse commands from the transcription using keyword matching.

```typescript
interface VoiceCommand {
    trigger: string[];           // Phrases that trigger this command
    action: string;              // VS Code command to execute
    params?: (match: string) => any;  // Extract parameters
    terminal?: boolean;          // Is this a terminal command?
}

const VOICE_COMMANDS: VoiceCommand[] = [
    // Execution
    {
        trigger: ['enter', 'send', 'submit', 'run that', 'execute'],
        action: 'terminal.send-enter',
        terminal: true
    },
    {
        trigger: ['cancel', 'stop that', 'abort'],
        action: 'terminal.send-ctrl-c',
        terminal: true
    },

    // Editing
    {
        trigger: ['delete that', 'undo', 'scratch that'],
        action: 'undo'
    },
    {
        trigger: ['clear line', 'delete line'],
        action: 'editor.action.deleteLines'
    },
    {
        trigger: ['select all'],
        action: 'editor.action.selectAll'
    },
    {
        trigger: ['new line', 'newline'],
        action: 'type',
        params: () => ({ text: '\n' })
    },

    // Navigation
    {
        trigger: ['go to line'],
        action: 'workbench.action.gotoLine',
        params: (match) => {
            const num = match.match(/go to line (\d+)/)?.[1];
            return num ? { lineNumber: parseInt(num) } : null;
        }
    },

    // VS Code
    {
        trigger: ['save file', 'save'],
        action: 'workbench.action.files.save'
    },
    {
        trigger: ['close file', 'close tab'],
        action: 'workbench.action.closeActiveEditor'
    },
    {
        trigger: ['open terminal', 'show terminal'],
        action: 'workbench.action.terminal.toggleTerminal'
    },
    {
        trigger: ['command palette'],
        action: 'workbench.action.showCommands'
    },

    // Dictation control
    {
        trigger: ['stop listening', 'pause'],
        action: 'voicecode.stopListening'
    }
];
```

**Pros:**
- Predictable behavior
- Fast execution
- No LLM required

**Cons:**
- Limited to predefined commands
- No fuzzy matching

### Option B: LLM-Based Command Parsing

Use the LLM to interpret intent and generate commands.

```python
COMMAND_PROMPT = """Parse voice commands from the transcription.

Available commands:
- ENTER: Send the command (trigger: "enter", "send", "submit")
- CANCEL: Cancel current operation (trigger: "cancel", "stop")
- UNDO: Undo last action (trigger: "undo", "delete that")
- GOTO_LINE: Go to line number (trigger: "go to line N")
- TEXT: Regular text to insert

Input: "{text}"

Output JSON:
{{"type": "COMMAND_TYPE", "params": {{}}, "remaining_text": "text after command"}}

Examples:
Input: "create a function called hello enter"
Output: {{"commands": [{{"type": "TEXT", "value": "create a function called hello"}}, {{"type": "ENTER"}}]}}

Input: "go to line 42"
Output: {{"commands": [{{"type": "GOTO_LINE", "params": {{"line": 42}}}}]}}
"""
```

**Pros:**
- Handles variations naturally
- Can understand context
- Extensible via prompt

**Cons:**
- Additional latency
- May misinterpret
- Requires LLM call

### Option C: Hybrid (Keyword + LLM Fallback)

Try keyword matching first, use LLM for ambiguous cases.

```typescript
async function parseCommands(text: string): Promise<ParsedResult> {
    // Try keyword matching first
    const keywordResult = parseWithKeywords(text);

    if (keywordResult.confident) {
        return keywordResult;
    }

    // Fall back to LLM for complex cases
    return await parseWithLLM(text);
}

function parseWithKeywords(text: string): ParsedResult {
    const commands: Command[] = [];
    let remainingText = text.toLowerCase();

    for (const cmd of VOICE_COMMANDS) {
        for (const trigger of cmd.trigger) {
            if (remainingText.endsWith(trigger)) {
                commands.push({
                    action: cmd.action,
                    params: cmd.params?.(remainingText)
                });
                remainingText = remainingText.slice(0, -trigger.length).trim();
            }
        }
    }

    return {
        commands,
        text: remainingText,
        confident: commands.length > 0 || !containsCommandLikeWords(remainingText)
    };
}
```

## Decision

**Option A: Keyword Detection** with well-defined command vocabulary

Rationale:
1. Predictable, consistent behavior
2. No additional latency
3. Users can learn the vocabulary
4. Commands are clearly separated from text

## Implementation Details

### Command Parser

```typescript
interface ParsedTranscription {
    text: string;              // Text to insert
    commands: Command[];       // Commands to execute
    hasTrailingCommand: boolean;  // Ends with a command
}

class CommandParser {
    private commands: VoiceCommand[];

    constructor(commands: VoiceCommand[]) {
        this.commands = commands;
    }

    parse(transcription: string): ParsedTranscription {
        let text = transcription;
        const foundCommands: Command[] = [];

        // Check for commands at the end of transcription
        for (const cmd of this.commands) {
            for (const trigger of cmd.trigger) {
                const regex = new RegExp(`\\s*${this.escapeRegex(trigger)}\\s*$`, 'i');
                if (regex.test(text)) {
                    text = text.replace(regex, '').trim();
                    foundCommands.push({
                        action: cmd.action,
                        params: cmd.params?.(transcription),
                        terminal: cmd.terminal
                    });
                }
            }
        }

        return {
            text,
            commands: foundCommands.reverse(),  // Execute in order spoken
            hasTrailingCommand: foundCommands.length > 0
        };
    }

    private escapeRegex(str: string): string {
        return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }
}
```

### Command Executor

```typescript
class CommandExecutor {
    async execute(command: Command): Promise<void> {
        if (command.terminal) {
            await this.executeTerminalCommand(command);
        } else {
            await vscode.commands.executeCommand(
                command.action,
                command.params
            );
        }
    }

    private async executeTerminalCommand(command: Command): Promise<void> {
        const terminal = vscode.window.activeTerminal;
        if (!terminal) return;

        switch (command.action) {
            case 'terminal.send-enter':
                terminal.sendText('', true);  // Empty string with execute=true
                break;
            case 'terminal.send-ctrl-c':
                terminal.sendText('\x03', false);
                break;
            case 'terminal.clear-line':
                terminal.sendText('\u0015', false);  // Ctrl+U
                break;
        }
    }
}
```

### Integration with Transcription Pipeline

```typescript
async function processTranscription(rawText: string): Promise<void> {
    // 1. Clean up with LLM
    const cleanedText = await llmCleanup(rawText);

    // 2. Parse commands
    const parsed = commandParser.parse(cleanedText);

    // 3. Insert text (if any)
    if (parsed.text) {
        await insertText(parsed.text);
    }

    // 4. Execute commands
    for (const cmd of parsed.commands) {
        await commandExecutor.execute(cmd);
    }
}
```

### Configurable Commands

Allow users to customize in settings:

```json
