   192→            vscode.commands.registerCommand('vtthought.disconnectBackend', () => {
   193→                this.disconnect();
   194→            }),
   195→            // Authentication commands (ADR-002)
   196→            vscode.commands.registerCommand('vtthought.setupAuthentication', async () => {
   197→                await this.setupAuthentication();
   198→            }),
   199→            vscode.commands.registerCommand('vtthought.clearAuthentication', async () => {
   200→                await this.clearAuthentication();
   201→            }),
   202→            vscode.commands.registerCommand('vtthought.showAuthenticationStatus', async () => {
   203→                await this.showAuthenticationStatus();
   204→            }),
   205→            // First-run setup commands (ADR-017)
   206→            vscode.commands.registerCommand('vtthought.runSetup', async () => {
   207→                await this.runSetup();
   208→            }),
   209→            vscode.commands.registerCommand('vtthought.resetSetup', async () => {
   210→                await this.resetSetup();
   211→            })
   212→        );
   213→
   214→        this.log('Commands registered');
   215→    }
   216→
   217→    /**
   218→     * Toggle recording state
   219→     */
   220→    private toggleRecording(): void {
   221→        if (!this.state.isConnected) {
   222→            vscode.window.showWarningMessage(
   223→                'VTThought is not connected to the backend. Connect first.'
   224→            );
   225→            return;
   226→        }
   227→
   228→        this.state.isRecording = !this.state.isRecording;
   229→        this.updateStatusDisplay();
   230→
   231→        if (this.state.isRecording) {
   232→            this.startRecording();
   233→        } else {
   234→            this.stopRecording();
   235→        }
   236→    }
   237→
   238→    /**
   239→     * Start recording
   240→     */
   241→    private startRecording(): void {
   242→        this.log('Starting recording...');
   243→
   244→        // Send start signal to backend
   245→        if (this.audioStreamer?.isConnected) {
   246→            this.audioStreamer.startRecording();
   247→        }
   248→
   249→        // Start audio capture in WebView
   250→        this.voiceInputViewProvider.startRecording();
   251→
   252→        vscode.window.showInformationMessage('VTThought: Recording started');
   253→    }
   254→
   255→    /**
   256→     * Stop recording
   257→     */
   258→    private stopRecording(): void {
   259→        this.log('Stopping recording...');
   260→
   261→        // Stop audio capture in WebView
   262→        this.voiceInputViewProvider.stopRecording();
   263→
   264→        // Send stop signal to backend
   265→        if (this.audioStreamer?.isConnected) {
   266→            this.audioStreamer.stopRecording();
   267→        }
   268→
   269→        vscode.window.showInformationMessage('VTThought: Recording stopped');
   270→    }
   271→
   272→    /**
   273→     * Handle audio data from WebView
   274→     */
   275→    private handleAudioData(data: Float32Array, sampleRate: number): void {
   276→        // Stream audio to backend via WebSocket
   277→        if (this.audioStreamer?.isConnected) {
   278→            try {
   279→                this.audioStreamer.sendAudio(data);
   280→            } catch (error) {
   281→                this.log(`Failed to send audio data: ${error}`);
   282→            }
   283→        }
   284→    }
   285→
   286→    /**
   287→     * Setup authentication (ADR-002)
   288→     */
   289→    private async setupAuthentication(): Promise<void> {
   290→        this.log('Starting authentication setup...');
   291→
   292→        // Step 1: Get backend URL
   293→        const backendUrl = await vscode.window.showInputBox({
   294→            prompt: 'Enter your VTThought backend URL',
   295→            value: this.state.backendUrl,
   296→            placeHolder: 'http://localhost:8000',
   297→            validateInput: (value) => {
   298→                if (!value || !value.startsWith('http')) {
   299→                    return 'Please enter a valid URL (http:// or https://)';
   300→                }
   301→                return null;
   302→            }
   303→        });
   304→
   305→        if (!backendUrl) {
   306→            this.log('Authentication setup cancelled: No backend URL provided');
   307→            return;
   308→        }
   309→
   310→        // Normalize URL (remove trailing slash)
   311→        const normalizedUrl = backendUrl.replace(/\/$/, '');
   312→        await this.tokenManager.storeBackendUrl(normalizedUrl);
   313→        this.state.backendUrl = normalizedUrl;
   314→
   315→        // Step 2: Test backend connection
   316→        this.log(`Testing connection to ${normalizedUrl}...`);
   317→        try {
   318→            const response = await fetch(`${normalizedUrl}/api/auth/mode`);
   319→            if (!response.ok) {
   320→                throw new Error(`HTTP ${response.status}`);
   321→            }
   322→
   323→            const authMode = await response.json() as { mode: string; single_user_mode: boolean };
   324→            this.log(`Backend auth mode: ${authMode.mode}`);
   325→
   326→            if (authMode.single_user_mode) {
   327→                // Single-user mode: no token needed
   328→                vscode.window.showInformationMessage(
   329→                    'VTThought: Backend configured in single-user mode. No token required.'
   330→                );
   331→                this.state.isAuthenticated = true;
   332→                this.updateStatusDisplay();
   333→                return;
   334→            }
   335→        } catch (error) {
   336→            const message = error instanceof Error ? error.message : String(error);
   337→            vscode.window.showErrorMessage(
   338→                `VTThought: Failed to connect to backend at ${normalizedUrl}. ${message}`
   339→            );
   340→            this.log(`Backend connection failed: ${message}`);
   341→            return;
   342→        }
   343→
   344→        // Step 3: Get token from user
   345→        const token = await vscode.window.showInputBox({
   346→            prompt: 'Enter your VTThought extension token (from backend settings)',
   347→            password: true,
   348→            placeHolder: 'vct_...',
   349→            validateInput: (value) => {
   350→                if (!value || !value.startsWith('vct_')) {
   351→                    return 'Please enter a valid token (starts with vct_)';
   352→                }
   353→                return null;
   354→            }
   355→        });
   356→
   357→        if (!token) {
   358→            this.log('Authentication setup cancelled: No token provided');
   359→            return;
   360→        }
   361→
   362→        // Store token
   363→        await this.tokenManager.storeToken(token);
   364→        this.state.isAuthenticated = true;
   365→
   366→        this.log('Authentication configured successfully');
   367→        vscode.window.showInformationMessage(
   368→            'VTThought: Authentication configured successfully!'
   369→        );
   370→        this.updateStatusDisplay();
   371→    }
   372→
   373→    /**
   374→     * Clear authentication (ADR-002)
   375→     */
   376→    private async clearAuthentication(): Promise<void> {
   377→        const result = await vscode.window.showWarningMessage(
   378→            'Are you sure you want to clear your authentication settings?',
   379→            { modal: true },
   380→            'Clear',
   381→            'Cancel'
   382→        );
   383→
   384→        if (result === 'Clear') {
   385→            await this.tokenManager.clearAll();
   386→            this.state.isAuthenticated = false;
   387→            this.disconnect();
   388→            this.log('Authentication cleared');
   389→            vscode.window.showInformationMessage('VTThought: Authentication cleared');
   390→            this.updateStatusDisplay();
   391→        }
   392→    }
   393→
   394→    /**
   395→     * Show authentication status (ADR-002)
   396→     */
   397→    private async showAuthenticationStatus(): Promise<void> {
   398→        const authStatus = await getAuthStatus(this.tokenManager);
   399→
   400→        const message = `
   401→VTThought Authentication Status
   402→===============================
   403→Authenticated: ${authStatus.isConfigured ? 'Yes' : 'No'}
   404→Backend URL: ${authStatus.backendUrl}
   405→`.trim();
   406→
   407→        this.log(message);
   408→        vscode.window.showInformationMessage(message);
   409→    }
   410→
   411→    /**
   412→     * Run the first-run setup flow (ADR-017)
   413→     */
   414→    private async runSetup(): Promise<void> {
   415→        this.log('Starting setup flow...');
   416→        const setupFlow = new SetupFlow(this.context, this.tokenManager);
   417→        await setupFlow.start();
   418→    }
   419→
   420→    /**
   421→     * Reset the first-run setup (ADR-017)
   422→     */
   423→    private async resetSetup(): Promise<void> {
   424→        const result = await vscode.window.showWarningMessage(
   425→            'This will reset VTThought to first-run state. You will need to set up authentication again.',
   426→            { modal: true },
   427→            'Reset',
   428→            'Cancel'
   429→        );
   430→
   431→        if (result === 'Reset') {
   432→            await SetupFlow.reset(this.context);
   433→            await this.tokenManager.clearAll();
   434→            this.state.isAuthenticated = false;
   435→            this.disconnect();
   436→            this.log('Setup reset');
   437→            vscode.window.showInformationMessage(
   438→                'VTThought has been reset. Click the status bar or run "VTThought: Run Setup" to start again.'
   439→            );
   440→            this.updateStatusDisplay();
   441→        }
   442→    }
   443→
   444→    /**
   445→     * Connect to backend WebSocket
   446→     */
   447→    private async connectBackend(): Promise<void> {
   448→        // Check authentication first (ADR-002)
   449→        if (!this.state.isAuthenticated) {
   450→            const result = await vscode.window.showWarningMessage(
   451→                'VTThought is not configured. Would you like to set up authentication?',
   452→                'Setup',
   453→                'Cancel'
   454→            );
   455→
   456→            if (result === 'Setup') {
   457→                await this.setupAuthentication();
   458→                if (!this.state.isAuthenticated) {
   459→                    this.log('Connection cancelled: Authentication not configured');
   460→                    return;
   461→                }
   462→            } else {
   463→                this.log('Connection cancelled: Authentication not configured');
   464→                return;
   465→            }
   466→        }
   467→
   468→        const apiUrl = await this.tokenManager.getBackendUrl();
   469→        const wsUrl = await this.tokenManager.getWebSocketUrl();
   470→
   471→        this.log(`Connecting to backend: ${apiUrl}`);
   472→
   473→        try {
   474→            // First, verify backend is reachable via health check
   475→            const authHeader = await this.tokenManager.getAuthHeader();
   476→            const headers: Record<string, string> = {};
   477→            if (authHeader) {
   478→                headers['Authorization'] = authHeader;
   479→            }
   480→
   481→            const response = await fetch(`${apiUrl}/api/health`, { headers });
   482→
   483→            if (!response.ok) {
   484→                if (response.status === 401) {
   485→                    // Token expired or invalid
   486→                    await this.tokenManager.clearToken();
   487→                    this.state.isAuthenticated = false;
   488→                    vscode.window.showErrorMessage(
   489→                        'VTThought: Authentication failed. Please set up authentication again.',
   490→                        'Setup'
   491→                    ).then(action => {
   492→                        if (action === 'Setup') {
   493→                            vscode.commands.executeCommand('vtthought.setupAuthentication');
   494→                        }
   495→                    });
   496→                    return;
   497→                }
   498→                throw new Error(`Health check failed: ${response.status}`);
   499→            }
   500→
   501→            // Establish WebSocket connection
   502→            this.audioStreamer = new AudioStreamer(wsUrl, { sampleRate: 16000, channels: 1 }, {
   503→                onConnected: () => {
   504→                    this.state.isConnected = true;
   505→                    this.updateStatusDisplay();
   506→                    this.log('WebSocket connected successfully');
   507→                },
   508→                onDisconnected: () => {
   509→                    this.state.isConnected = false;
   510→                    this.state.isRecording = false;
   511→                    this.updateStatusDisplay();
   512→                    this.log('WebSocket disconnected');
   513→                },
   514→                onError: (error) => {
   515→                    this.log(`WebSocket error: ${error.message}`);
   516→                    vscode.window.showErrorMessage(`VTThought: WebSocket error - ${error.message}`);
   517→                },
   518→                onMessage: async (message) => {
   519→                    // Handle server messages (interim, streaming, final, error)
   520→                    if (this.dictationHandler) {
   521→                        await this.dictationHandler.handleMessage(message);
   522→                    }
   523→                }
   524→            });
   525→
   526→            await this.audioStreamer.connect();
   527→
   528→            this.log('Connected to backend successfully');
   529→            vscode.window.showInformationMessage('VTThought: Connected to backend');
   530→
   531→        } catch (error) {
   532→            this.log(`Connection failed: ${error}`);
   533→            vscode.window.showErrorMessage(
   534→                `VTThought: Failed to connect to backend at ${apiUrl}. Ensure the backend is running and try again.`
   535→            );
   536→            this.state.isConnected = false;
   537→            this.updateStatusDisplay();
   538→        }
   539→    }
   540→
   541→    /**
   542→     * Disconnect from backend
   543→     */
   544→    private disconnect(): void {
   545→        // Stop recording if active
   546→        if (this.state.isRecording) {
   547→            this.stopRecording();
   548→        }
   549→
   550→        // Close WebSocket connection
   551→        if (this.audioStreamer) {
   552→            this.audioStreamer.close();
   553→            this.audioStreamer = null;
   554→        }
   555→
   556→        this.state.isConnected = false;
   557→        this.state.isRecording = false;
   558→        this.updateStatusDisplay();
   559→
   560→        this.log('Disconnected from backend');
   561→        vscode.window.showInformationMessage('VTThought: Disconnected from backend');
   562→    }
   563→
   564→    /**
   565→     * Update status bar display
   566→     */
   567→    private updateStatusDisplay(): void {
   568→        // Recording status
   569→        if (this.state.isRecording) {
   570→            this.statusBarItem.text = '$record VTThought: Recording';
   571→            this.statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
   572→            this.statusBarItem.tooltip = 'Click to stop recording';
   573→        } else {
   574→            this.statusBarItem.text = '$circle-large-outline VTThought: Idle';
   575→            this.statusBarItem.backgroundColor = undefined;
   576→            this.statusBarItem.tooltip = 'Click to start recording (Ctrl+Alt+V)';
   577→        }
   578→
   579→        // Connection status
   580→        if (this.state.isConnected) {
   581→            this.connectionStatusBarItem.text = '$radio-tower VTThought: Connected';
   582→            this.connectionStatusBarItem.tooltip = 'Connected to backend';
   583→            this.connectionStatusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.prominentBackground');
   584→        } else {
   585→            this.connectionStatusBarItem.text = '$circle-large-outline VTThought: Disconnected';
   586→            this.connectionStatusBarItem.tooltip = 'Click to connect to backend';
   587→            this.connectionStatusBarItem.backgroundColor = undefined;
   588→        }
   589→    }
   590→
   591→    /**
   592→     * Handle configuration changes
   593→     */
   594→    private handleConfigurationChange(): void {
   595→        const config = vscode.workspace.getConfiguration('vtthought');
   596→        this.state.backendUrl = config.get('backendUrl', 'ws://localhost:8000/ws/audio');
   597→
   598→        this.log('Configuration changed - reconnecting...');
   599→        if (this.state.isConnected) {
   600→            this.disconnect();
   601→            this.connectBackend().catch(err => {
   602→                this.log(`Reconnect failed: ${err}`);
   603→            });
   604→        }
   605→    }
   606→
   607→    /**
